begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data) values ('64000000-0000-4000-8000-000000000001','ori64-1@example.invalid',now(),'{"full_name":"Synthetic manager 1","phone":"11900000000","is_sindico":true}');
insert into auth.sessions(id,user_id) values ('64000000-0000-4000-9000-000000000001','64000000-0000-4000-8000-000000000001');
insert into condominiums(id,manager_id,name,address) values ('64000000-0000-4000-8000-000000000001','64000000-0000-4000-8000-000000000001','Synthetic ORI64 1','Synthetic address');
select set_config('ori64.slug1', (select slug from condominiums where id='64000000-0000-4000-8000-000000000001'), true);
insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data) values ('64000000-0000-4000-8000-000000000002','ori64-2@example.invalid',now(),'{"full_name":"Synthetic manager 2","phone":"11900000000","is_sindico":true}');
insert into auth.sessions(id,user_id) values ('64000000-0000-4000-9000-000000000002','64000000-0000-4000-8000-000000000002');
insert into condominiums(id,manager_id,name,address) values ('64000000-0000-4000-8000-000000000002','64000000-0000-4000-8000-000000000002','Synthetic ORI64 2','Synthetic address');
select set_config('ori64.slug2', (select slug from condominiums where id='64000000-0000-4000-8000-000000000002'), true);
set local role service_role;
select set_config('ori64.created', (select occurrence_id::text from public.register_public_occurrence_with_suggestion(current_setting('ori64.slug1'),'Synthetic reporter','11900000000','Apartment synthetic','Synthetic public report','Synthetic hall','normal','Sem sinal de risco no relato.','rules')),true);
select throws_ok($$select * from occurrences$$,'42501',null,'Public writer credential cannot read private records');
select throws_ok($$select append_occurrence_note(current_setting('ori64.created')::uuid,'Forbidden')$$,'42501',null,'Public entry cannot perform manager action');
select throws_ok($$select private.append_occurrence_event(current_setting('ori64.created')::uuid,'completed')$$,'42501',null,'Public entry cannot call private event writer');
select throws_ok($$select public.register_public_occurrence_with_suggestion(current_setting('ori64.slug1'),null,'11900000000','Apartment synthetic','Synthetic public report','Synthetic hall','normal','Sem sinal de risco no relato.','rules')$$,'22023','Invalid public registration.','Public RPC rejects invalid reporter_name');
select throws_ok($$select public.register_public_occurrence_with_suggestion(current_setting('ori64.slug1'),'Synthetic reporter','123','Apartment synthetic','Synthetic public report','Synthetic hall','normal','Sem sinal de risco no relato.','rules')$$,'22023','Invalid public registration.','Public RPC rejects invalid reporter_phone');
select throws_ok($$select public.register_public_occurrence_with_suggestion(current_setting('ori64.slug1'),'Synthetic reporter','11900000000',null,'Synthetic public report','Synthetic hall','normal','Sem sinal de risco no relato.','rules')$$,'22023','Invalid public registration.','Public RPC rejects invalid reporter_unit_or_role');
select throws_ok($$select public.register_public_occurrence_with_suggestion(current_setting('ori64.slug1'),'Synthetic reporter','11900000000','   ','Synthetic public report','Synthetic hall','normal','Sem sinal de risco no relato.','rules')$$,'22023','Invalid public registration.','Public RPC rejects invalid reporter_unit_or_role');
select throws_ok($$select public.register_public_occurrence_with_suggestion(current_setting('ori64.slug1'),'Synthetic reporter','11900000000','Apartment synthetic','   ','Synthetic hall','normal','Sem sinal de risco no relato.','rules')$$,'22023','Invalid public registration.','Public RPC rejects invalid description');
select throws_ok($$select public.register_public_occurrence_with_suggestion('missing-abcd','Synthetic reporter','11900000000','Apartment synthetic','Synthetic public report','Synthetic hall','normal','Sem sinal de risco no relato.','rules')$$,'22023','Invalid public registration.','Public RPC rejects invalid condominium_slug');
select throws_ok($$select public.register_public_occurrence_with_suggestion(condominium_slug=>current_setting('ori64.slug1'),reporter_name=>'Synthetic reporter'::text,reporter_phone=>'11900000000'::text,reporter_unit_or_role=>'Apartment synthetic'::text,description=>'Synthetic report'::text,location=>'Synthetic hall'::text,calculated_priority=>'normal'::text,calculated_reason=>'Sem sinal de risco no relato.'::text,calculated_source=>'rules'::text,target_occurrence=>current_setting('ori64.created')::uuid)$$,'42883',null,'Public RPC cannot accept target_occurrence');
select throws_ok($$select public.register_public_occurrence_with_suggestion(condominium_slug=>current_setting('ori64.slug1'),reporter_name=>'Synthetic reporter'::text,reporter_phone=>'11900000000'::text,reporter_unit_or_role=>'Apartment synthetic'::text,description=>'Synthetic report'::text,location=>'Synthetic hall'::text,calculated_priority=>'normal'::text,calculated_reason=>'Sem sinal de risco no relato.'::text,calculated_source=>'rules'::text,author_type=>'system'::text)$$,'42883',null,'Public RPC cannot accept author_type');
select throws_ok($$select public.register_public_occurrence_with_suggestion(condominium_slug=>current_setting('ori64.slug1'),reporter_name=>'Synthetic reporter'::text,reporter_phone=>'11900000000'::text,reporter_unit_or_role=>'Apartment synthetic'::text,description=>'Synthetic report'::text,location=>'Synthetic hall'::text,calculated_priority=>'normal'::text,calculated_reason=>'Sem sinal de risco no relato.'::text,calculated_source=>'rules'::text,visible_to_resident=>true)$$,'42883',null,'Public RPC cannot accept visible_to_resident');
select throws_ok($$select public.register_public_occurrence_with_suggestion(condominium_slug=>current_setting('ori64.slug1'),reporter_name=>'Synthetic reporter'::text,reporter_phone=>'11900000000'::text,reporter_unit_or_role=>'Apartment synthetic'::text,description=>'Synthetic report'::text,location=>'Synthetic hall'::text,calculated_priority=>'normal'::text,calculated_reason=>'Sem sinal de risco no relato.'::text,calculated_source=>'rules'::text,condominium_id=>'64000000-0000-4000-8000-000000000002'::uuid)$$,'42883',null,'Public RPC cannot accept condominium_id');
select throws_ok($$select public.register_public_occurrence_with_suggestion(current_setting('ori64.slug1'),repeat('x',201),'11900000000','Apartment synthetic','Synthetic public report','Synthetic hall','normal','Sem sinal de risco no relato.','rules')$$,'22023','Invalid public registration.','Direct RPC enforces reporter_name length');
select throws_ok($$select public.register_public_occurrence_with_suggestion(current_setting('ori64.slug1'),'Synthetic reporter','11900000000',repeat('x',201),'Synthetic public report','Synthetic hall','normal','Sem sinal de risco no relato.','rules')$$,'22023','Invalid public registration.','Direct RPC enforces reporter_unit_or_role length');
select throws_ok($$select public.register_public_occurrence_with_suggestion(current_setting('ori64.slug1'),'Synthetic reporter','11900000000','Apartment synthetic',repeat('x',10001),'Synthetic hall','normal','Sem sinal de risco no relato.','rules')$$,'22023','Invalid public registration.','Direct RPC enforces description length');
reset role;
select is((select count(*) from occurrences where id=current_setting('ori64.created')::uuid),1::bigint,'Public creation writes one occurrence');
select is((select count(*) from occurrence_events where occurrence_id=current_setting('ori64.created')::uuid),1::bigint,'Public creation writes exactly one initial event');
select ok((select origin='public_form' and channel='web' and created_by_profile_id is null and registered_at>=transaction_timestamp() from occurrences where id=current_setting('ori64.created')::uuid),'Public origin and server time derived');
select ok((select event_type='registered' and author_type='reporter' and author_profile_id is null and author_name='Synthetic reporter' and author_phone='11900000000' and author_role='Apartment synthetic' and not is_human_action and visible_to_resident and data='{"identity":"self_declared"}'::jsonb from occurrence_events where occurrence_id=current_setting('ori64.created')::uuid),'Reporter identity explicitly self-declared with required snapshots');
select is((select internal_description from occurrence_events where occurrence_id=current_setting('ori64.created')::uuid),'Registrou a ocorrência pelo formulário. Unidade informada: Apartment synthetic','Exact first event text');
select ok((select e.public_text=e.internal_description and e.occurred_at=o.registered_at from occurrence_events e join occurrences o on o.id=e.occurrence_id where o.id=current_setting('ori64.created')::uuid),'Registration projection and server timestamp agree');
select throws_ok($$select private.append_occurrence_event(current_setting('ori64.created')::uuid,'registered')$$,'23505',null,'Second registration cannot be added');
select throws_ok($$select private.append_occurrence_event(current_setting('ori64.created')::uuid,'ai_suggestion')$$,'22023',null,'AI event unsupported by shared writer');
select throws_ok($$select private.append_occurrence_event(current_setting('ori64.created')::uuid,'priority_changed')$$,'22023',null,'Priority event unsupported by shared writer');
create function pg_temp.reject_initial_event() returns trigger language plpgsql as $$ begin raise exception 'Controlled initial event failure'; end; $$;
create trigger ori64_test_failure after insert on public.occurrence_events for each row when (new.event_type='registered') execute function pg_temp.reject_initial_event();
set local role service_role;
select throws_ok($$select public.register_public_occurrence_with_suggestion(current_setting('ori64.slug1'),'Synthetic reporter','11900000000','Apartment synthetic','ORI64 rollback sentinel','Synthetic hall','normal','Sem sinal de risco no relato.','rules')$$,'P0001','Controlled initial event failure','Actual event write failure propagates');
reset role;
drop trigger ori64_test_failure on public.occurrence_events;
select is((select count(*) from occurrences where description='ORI64 rollback sentinel'),0::bigint,'Event failure rolls occurrence back');
select is((select count(*) from occurrence_events where occurrence_id=current_setting('ori64.created')::uuid),1::bigint,'Failed event leaves no extra history');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"64000000-0000-4000-8000-000000000001","session_id":"64000000-0000-4000-9000-000000000001","role":"authenticated"}',true);
select lives_ok($$select public.append_occurrence_note(current_setting('ori64.created')::uuid,'Synthetic internal note')$$,'Original RPC reuses shared writer successfully');
select is((select count(*) from occurrences),1::bigint,'Owner sees registered occurrence');
select is((select count(*) from occurrence_events),2::bigint,'Owner sees initial history and note');
select throws_ok($$select public.register_public_occurrence_with_suggestion(current_setting('ori64.slug1'),'Synthetic reporter','11900000000','Apartment synthetic','Synthetic public report','Synthetic hall','normal','Sem sinal de risco no relato.','rules')$$,'42501',null,'Authenticated cannot use server-only public entry');
select throws_ok($$select private.append_occurrence_event(current_setting('ori64.created')::uuid,'completed')$$,'42501',null,'Authenticated cannot bypass event wrapper');
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"64000000-0000-4000-8000-000000000002","session_id":"64000000-0000-4000-9000-000000000002","role":"authenticated"}',true);
select is((select count(*) from occurrences),0::bigint,'Other manager sees no public-created occurrence');
select is((select count(*) from occurrence_events),0::bigint,'Other manager sees no history');
select throws_ok($$select public.append_occurrence_note(current_setting('ori64.created')::uuid,'Forbidden')$$,'42501','Occurrence unavailable.','Other portfolio append denied');
select throws_ok($$select public.register_public_occurrence_with_suggestion(current_setting('ori64.slug1'),'Synthetic reporter','11900000000','Apartment synthetic','Synthetic public report','Synthetic hall','normal','Sem sinal de risco no relato.','rules')$$,'42501',null,'Authenticated cannot use server-only public entry');
select throws_ok($$select private.append_occurrence_event(current_setting('ori64.created')::uuid,'completed')$$,'42501',null,'Authenticated cannot bypass event wrapper');
reset role;
update profiles set full_name='Changed manager',phone='11800000000',is_sindico=false where id='64000000-0000-4000-8000-000000000001';
select ok((select author_name='Synthetic manager 1' and author_phone='11900000000' and author_role='manager' and not visible_to_resident and public_text is null and data='{}'::jsonb and occurred_at>=transaction_timestamp() from occurrence_events where event_type='manager_update'),'Manager snapshot and internal projection survive profile edits/deactivation');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"64000000-0000-4000-8000-000000000001","session_id":"64000000-0000-4000-9000-000000000001","role":"authenticated"}',true);
select throws_ok($$select append_occurrence_note(current_setting('ori64.created')::uuid,'Forbidden')$$,'42501','Occurrence unavailable.','Deactivated manager cannot append');
reset role;
update profiles set is_sindico=true where id='64000000-0000-4000-8000-000000000001';
delete from auth.sessions where id='64000000-0000-4000-9000-000000000001';
set local role authenticated;
select throws_ok($$select append_occurrence_note(current_setting('ori64.created')::uuid,'Forbidden')$$,'42501','Active authenticated session required.','Revoked session cannot append through shared writer');
select set_config('request.jwt.claims','{"sub":"64000000-0000-4000-8000-000000000001","session_id":"invalid","role":"authenticated"}',true);
select throws_ok($$select append_occurrence_note(current_setting('ori64.created')::uuid,'Forbidden')$$,'42501','Active authenticated session required.','Invalid session cannot append through shared writer');
reset role;
update occurrences set final_priority='normal',ai_failure_reason='Synthetic failure' where id=current_setting('ori64.created')::uuid;
select is((select count(*) from occurrence_events where occurrence_id=current_setting('ori64.created')::uuid),2::bigint,'Final priority and failure fields do not add human events or overwrite the original suggestion');
select ok((select author_name='Synthetic reporter' and author_type='reporter' and author_profile_id is null from occurrence_events where event_type='registered' and occurrence_id=current_setting('ori64.created')::uuid),'Reporter remains distinct from changed manager profile');
insert into occurrence_events(occurrence_id,event_type,author_type,author_name,internal_description,is_human_action,occurred_at,priority_snapshot,responsible_name,delegation_started_at) values (current_setting('ori64.created')::uuid,'responsible_changed','manager','Synthetic metric manager','Synthetic delegation',true,transaction_timestamp()+interval '1 hour','urgent','Synthetic employee',transaction_timestamp()+interval '1 hour');
insert into occurrence_events(occurrence_id,event_type,author_type,author_name,internal_description,is_human_action,occurred_at,priority_snapshot,delegation_started_at) select occurrence_id,'completed','manager','Synthetic metric manager','Synthetic completion',true,transaction_timestamp()+interval '2 hours','urgent',delegation_started_at from occurrence_events where event_type='responsible_changed' and occurrence_id=current_setting('ori64.created')::uuid;
select ok((select min(occurred_at) filter(where is_human_action) >= min(occurred_at) filter(where event_type='registered') from occurrence_events where occurrence_id=current_setting('ori64.created')::uuid),'First human response metric has server timestamps');
select ok((select extract(epoch from occurred_at-delegation_started_at)>=0 from occurrence_events where event_type='completed' and occurrence_id=current_setting('ori64.created')::uuid),'Fixture completion supports delegation duration metric');
select is(has_function_privilege('anon','public.register_public_occurrence_with_suggestion(text,text,text,text,text,text,text,text,text)','EXECUTE'),'anon'='service_role','anon public registration execute is minimal');
select ok(not has_function_privilege('anon','private.append_occurrence_event(uuid,text,text)','EXECUTE'),'anon cannot call shared private writer');
select is(has_function_privilege('authenticated','public.register_public_occurrence_with_suggestion(text,text,text,text,text,text,text,text,text)','EXECUTE'),'authenticated'='service_role','authenticated public registration execute is minimal');
select ok(not has_function_privilege('authenticated','private.append_occurrence_event(uuid,text,text)','EXECUTE'),'authenticated cannot call shared private writer');
select is(has_function_privilege('service_role','public.register_public_occurrence_with_suggestion(text,text,text,text,text,text,text,text,text)','EXECUTE'),'service_role'='service_role','service_role public registration execute is minimal');
select ok(not has_function_privilege('service_role','private.append_occurrence_event(uuid,text,text)','EXECUTE'),'service_role cannot call shared private writer');
set local role anon;
select throws_ok($$select public.register_public_occurrence_with_suggestion(current_setting('ori64.slug1'),'Synthetic reporter','11900000000','Apartment synthetic','Synthetic public report','Synthetic hall','normal','Sem sinal de risco no relato.','rules')$$,'42501',null,'Anonymous cannot call registration without backend boundary');
reset role;
select ok(prosecdef and proconfig=array['search_path=""'], 'Public entry SECURITY DEFINER has fixed search_path') from pg_proc where oid='public.register_public_occurrence_with_suggestion(text,text,text,text,text,text,text,text,text)'::regprocedure;
select is((select event_type from occurrence_events where occurrence_id=current_setting('ori64.created')::uuid and is_human_action order by occurred_at,id limit 1),'manager_update','First human response uses the first authenticated note, not registration or later delegation');
select is((select extract(epoch from occurred_at-delegation_started_at)::bigint from occurrence_events where occurrence_id=current_setting('ori64.created')::uuid and event_type='completed'),3600::bigint,'Structured delegation/completion fixture yields exact metric duration');
select * from finish();
rollback;
